package com.example.json;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Thin wrapper around a shared, thread-safe Jackson mapper. */
public final class Json {

    private static final JsonMapper MAPPER = JsonMapper.builder().build();

    private Json() {
    }

    /** Parses JSON into the given type. */
    public static <T> T parse(String json, Class<T> type) {
        return MAPPER.readValue(json, type);
    }

    /** Parses JSON into a tree when no fixed type exists. */
    public static JsonNode parseTree(String json) {
        return MAPPER.readTree(json);
    }

    /** Serializes a value to compact JSON. */
    public static String write(Object value) {
        return MAPPER.writeValueAsString(value);
    }

    /** Serializes a value to indented JSON. */
    public static String writePretty(Object value) {
        return MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(value);
    }
}
EOF
cat > src/main/java/com/example/json/Main.java <<'EOF'
package com.example.json;

import java.util.List;

public class Main {
    public static void main(String[] args) {
        var person = new Person("Ada", 36, List.of("ada@example.com"));

        String json = Json.writePretty(person);
        System.out.println(json);

        Person parsed = Json.parse(json, Person.class);
        System.out.println(parsed);
    }
}
EOF
cat > src/test/java/com/example/json/JsonTest.java <<'EOF'
package com.example.json;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.List;
import org.junit.jupiter.api.Test;
import tools.jackson.core.JacksonException;

class JsonTest {

    @Test
    void roundTripsRecord() {
        var person = new Person("Ada", 36, List.of("ada@example.com"));
        assertEquals(person, Json.parse(Json.write(person), Person.class));
    }

    @Test
    void writesExpectedJson() {
        var person = new Person("Ada", 36, List.of());
        assertEquals("{\"name\":\"Ada\",\"age\":36,\"emails\":[]}", Json.write(person));
    }

    @Test
    void parsesTree() {
        var node = Json.parseTree("{\"a\":{\"b\":[1,2,3]}}");
        assertEquals(3, node.path("a").path("b").get(2).asInt());
    }

    @Test
    void rejectsMalformedJson() {
        assertThrows(JacksonException.class, () -> Json.parseTree("{not json"));
    }
}
EOF
